@@ -0,0 +1,34 @@
+import assert from 'node:assert/strict';
+import {readFileSync} from 'node:fs';
+const load = p => JSON.parse(readFileSync(p,'utf8'));
+const audit=load('docs/p9.0.7.2.4-official-version-coverage.json');
+const prior=load('docs/p9.0.7.2.3-primaries-articles-85.json');
+const policy=load('docs/p9.0.4.3-promotion-policy.json');
+assert.equal(audit.integrated_ci.head_sha,'f56f442db8b5df49e953ee90c7512d709b5ecaed');
+assert.equal(audit.integrated_ci.completed_workflows,10);
+assert.equal(audit.integrated_ci.successful_workflows,10);
+assert.equal(audit.integrated_ci.failed_workflows,0);
+assert.equal(audit.official_revision_records.length,7);
+assert.equal(new Set(audit.official_revision_records.map(x=>x.act_id)).size,7);
+assert(audit.official_revision_records.every(x=>x.original_revision_identified && x.verified_html_response_bytes>0 && /^[0-9a-f]{64}$/.test(x.verified_html_response_sha256)));
+assert(audit.official_revision_records.every(x=>x.response_digest_reproducibility==='NOT_CERTIFIED_DYNAMIC_HTML_PAGE' && x.hash_can_authorize_normative_release===false));
+assert.equal(audit.html_repeatability_test.identical,false);
+assert.equal(audit.html_repeatability_test.first_bytes,audit.html_repeatability_test.second_bytes);
+assert.notEqual(audit.html_repeatability_test.first_sha256,audit.html_repeatability_test.second_sha256);
+assert.equal(audit.cross_registry_exceptions.find(x=>x.act==='PMR-2026-114-ZID-VIII').new_regime_result,'ZERO_FOR_EXACT_NUMBER_QUERY');
+assert.equal(audit.official_revision_records.find(x=>x.act_id==='PMR-2025-223-ZI-VII').entry_into_force_rule,'DAY_AFTER_PUBLICATION_WITH_RETROACTIVE_REACH_2025-07-09');
+assert.equal(audit.official_revision_records.find(x=>x.act_id==='PMR-2025-187-ZI-VII').entry_into_force_rule,'2026-01-01');
+assert.deepEqual(audit.annual_coverage.map(x=>x.year),[2023,2024,2025,2026]);
+assert(audit.annual_coverage.every(x=>!x.official_minjust_register_complete && !x.official_council_all_act_publications_complete && !x.president_all_local_decrees_complete && !x.legacy_new_database_reconciled && !x.document_originals_sha256_complete && !x.independent_no_omission_proof));
+assert.equal(audit.scope_count,85);
+assert.equal(audit.identity_rows.length,85);
+assert.equal(new Set(audit.identity_rows.map(x=>x.actual_id)).size,85);
+assert.deepEqual(audit.identity_rows.map(x=>x.actual_id).sort(),prior.rows.map(x=>x.actual_id).sort());
+assert(audit.identity_rows.every(x=>x.legal_md_parent_preserved && x.archival_2024_2025_acts_checked.length===7 && !x.administrative_role_or_parent_change_for_this_id_certified && !x.full_territorial_membership_certified_2026 && !x.full_polygon_effective_control_certified && !x.p91_import_allowed));
+assert.equal(audit.exhaustiveness_certified,false);
+assert.equal(audit.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(audit.p91_import_allowed,false);
+assert.equal(audit.actual_mutation_allowed,false);
+assert.equal(policy.semantic_acceptance,'BLOCKED_INCOMPLETE');
+assert.equal(policy.p91_import_allowed,false);
+console.log('P90724_ARCHIVE_FAIL_CLOSED_PASS: #326 10/10 CI, 7 versioned 2024-25 legal texts, volatile HTML rejected, 85 IDs, P9.1 DENIED');
